mapper.sql:
AND b.tenant_id = #{p.tenantId}

    AND b.well_group_id IN (
        SELECT og.object_id
        FROM t_object_grant og
        WHERE og.tenant_id = #{p.tenantId}
          AND og.grantee_account = #{p.account}
          AND og.object_type = 'WELL_GROUP'
    )

sql.if:
AND EXISTS (
    SELECT 1
    FROM t_wellhead_reading r
    WHERE r.batch_id = b.id

        AND r.pressure_mpa >= #{p.pressureMin}


        AND r.pressure_mpa <= #{p.pressureMax}

)
